  'World History Trivia: 8 Dates That Changed Everything',
  'Eight questions on the dates and places that decided the modern world, from the fall of Constantinople to the Moon landing.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"In which year did the Second World War end?","options":[{"id":"a","text":"1918","is_correct":false},{"id":"b","text":"1939","is_correct":false},{"id":"c","text":"1945","is_correct":true},{"id":"d","text":"1950","is_correct":false}],"explanation":"The war in Europe ended in May 1945 and Japan surrendered in September of the same year."},{"id":"q2","question":"Which wall fell in 1989, becoming a symbol of the end of the Cold War?","options":[{"id":"a","text":"The Great Wall of China","is_correct":false},{"id":"b","text":"The Berlin Wall","is_correct":true},{"id":"c","text":"Hadrian''s Wall","is_correct":false},{"id":"d","text":"The Western Wall","is_correct":false}],"explanation":"The Berlin Wall came down on 9 November 1989 after 28 years dividing the city."},{"id":"q3","question":"Who was the first president of the United States?","options":[{"id":"a","text":"Thomas Jefferson","is_correct":false},{"id":"b","text":"John Adams","is_correct":false},{"id":"c","text":"George Washington","is_correct":true},{"id":"d","text":"Benjamin Franklin","is_correct":false}],"explanation":"George Washington took office in 1789 and served two terms."},{"id":"q4","question":"In which year did humans first walk on the Moon?","options":[{"id":"a","text":"1957","is_correct":false},{"id":"b","text":"1969","is_correct":true},{"id":"c","text":"1972","is_correct":false},{"id":"d","text":"1981","is_correct":false}],"explanation":"Apollo 11 landed on 20 July 1969; Neil Armstrong was the first person on the surface."},{"id":"q5","question":"Which ancient civilisation built the pyramids of Giza?","options":[{"id":"a","text":"Ancient Greece","is_correct":false},{"id":"b","text":"Ancient Egypt","is_correct":true},{"id":"c","text":"The Roman Empire","is_correct":false},{"id":"d","text":"Mesopotamia","is_correct":false}],"explanation":"The Great Pyramid was built for pharaoh Khufu around 2560 BC."},{"id":"q6","question":"In which year did the French Revolution begin?","options":[{"id":"a","text":"1688","is_correct":false},{"id":"b","text":"1776","is_correct":false},{"id":"c","text":"1789","is_correct":true},{"id":"d","text":"1815","is_correct":false}],"explanation":"The storming of the Bastille on 14 July 1789 is the conventional starting point."},{"id":"q7","question":"Which empire had its capital at Constantinople and fell in 1453?","options":[{"id":"a","text":"The Ottoman Empire","is_correct":false},{"id":"b","text":"The Byzantine Empire","is_correct":true},{"id":"c","text":"The Holy Roman Empire","is_correct":false},{"id":"d","text":"The Persian Empire","is_correct":false}],"explanation":"The Ottoman army took the city in 1453, ending the Eastern Roman Empire."},{"id":"q8","question":"Which Roman city was buried by the eruption of Mount Vesuvius in 79 AD?","options":[{"id":"a","text":"Ostia","is_correct":false},{"id":"b","text":"Carthage","is_correct":false},{"id":"c","text":"Pompeii","is_correct":true},{"id":"d","text":"Ravenna","is_correct":false}],"explanation":"Pompeii and nearby Herculaneum were buried in ash and preserved for centuries."}]'::jsonb,
  null,
  array['history', 'trivia', 'dates', 'world history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
