values (
  'es-trivia-historia-universal',
  'Trivia de historia universal: 8 fechas que cambiaron todo',
  'Ocho preguntas sobre las fechas y los lugares que decidieron el mundo moderno, desde la caída de Constantinopla hasta la llegada a la Luna.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿En qué año terminó la Segunda Guerra Mundial?","options":[{"id":"a","text":"1918","is_correct":false},{"id":"b","text":"1939","is_correct":false},{"id":"c","text":"1945","is_correct":true},{"id":"d","text":"1950","is_correct":false}],"explanation":"La guerra en Europa terminó en mayo de 1945 y Japón se rindió en septiembre de ese mismo año."},{"id":"q2","question":"¿Qué muro cayó en 1989 y se volvió símbolo del fin de la Guerra Fría?","options":[{"id":"a","text":"La Gran Muralla China","is_correct":false},{"id":"b","text":"El Muro de Berlín","is_correct":true},{"id":"c","text":"El Muro de Adriano","is_correct":false},{"id":"d","text":"El Muro de los Lamentos","is_correct":false}],"explanation":"El Muro de Berlín cayó el 9 de noviembre de 1989 tras 28 años dividiendo la ciudad."},{"id":"q3","question":"¿Quién fue el primer presidente de Estados Unidos?","options":[{"id":"a","text":"Thomas Jefferson","is_correct":false},{"id":"b","text":"John Adams","is_correct":false},{"id":"c","text":"George Washington","is_correct":true},{"id":"d","text":"Benjamin Franklin","is_correct":false}],"explanation":"George Washington asumió en 1789 y gobernó dos mandatos."},{"id":"q4","question":"¿En qué año llegó el ser humano a la Luna por primera vez?","options":[{"id":"a","text":"1957","is_correct":false},{"id":"b","text":"1969","is_correct":true},{"id":"c","text":"1972","is_correct":false},{"id":"d","text":"1981","is_correct":false}],"explanation":"El Apolo 11 aterrizó el 20 de julio de 1969; Neil Armstrong fue la primera persona en la superficie."},{"id":"q5","question":"¿Qué civilización antigua construyó las pirámides de Giza?","options":[{"id":"a","text":"La antigua Grecia","is_correct":false},{"id":"b","text":"El antiguo Egipto","is_correct":true},{"id":"c","text":"El Imperio romano","is_correct":false},{"id":"d","text":"Mesopotamia","is_correct":false}],"explanation":"La Gran Pirámide se construyó para el faraón Keops hacia el 2560 a. C."},{"id":"q6","question":"¿En qué año comenzó la Revolución Francesa?","options":[{"id":"a","text":"1688","is_correct":false},{"id":"b","text":"1776","is_correct":false},{"id":"c","text":"1789","is_correct":true},{"id":"d","text":"1815","is_correct":false}],"explanation":"La toma de la Bastilla el 14 de julio de 1789 es el punto de partida convencional."},{"id":"q7","question":"¿Qué imperio tenía su capital en Constantinopla y cayó en 1453?","options":[{"id":"a","text":"El Imperio otomano","is_correct":false},{"id":"b","text":"El Imperio bizantino","is_correct":true},{"id":"c","text":"El Sacro Imperio Romano","is_correct":false},{"id":"d","text":"El Imperio persa","is_correct":false}],"explanation":"El ejército otomano tomó la ciudad en 1453, poniendo fin al Imperio romano de Oriente."},{"id":"q8","question":"¿Qué ciudad romana quedó sepultada por la erupción del Vesubio en el año 79 d. C.?","options":[{"id":"a","text":"Ostia","is_correct":false},{"id":"b","text":"Cartago","is_correct":false},{"id":"c","text":"Pompeya","is_correct":true},{"id":"d","text":"Rávena","is_correct":false}],"explanation":"Pompeya y la cercana Herculano quedaron cubiertas de ceniza y se conservaron durante siglos."}]'::jsonb,
  null,
