insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-world-geography-trivia',
  'World Geography Trivia: Capitals, Oceans and Extremes',
  'Eight geography questions on capitals, oceans, deserts and the extremes of the planet. No trick questions, just the map.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'geography'),
  '[{"id":"q1","question":"What is the capital of Australia?","options":[{"id":"a","text":"Sydney","is_correct":false},{"id":"b","text":"Melbourne","is_correct":false},{"id":"c","text":"Canberra","is_correct":true},{"id":"d","text":"Perth","is_correct":false}],"explanation":"Canberra was purpose-built as the capital in 1913, between Sydney and Melbourne."},{"id":"q2","question":"Which is the largest ocean on Earth?","options":[{"id":"a","text":"Atlantic Ocean","is_correct":false},{"id":"b","text":"Indian Ocean","is_correct":false},{"id":"c","text":"Pacific Ocean","is_correct":true},{"id":"d","text":"Arctic Ocean","is_correct":false}],"explanation":"The Pacific covers about a third of the planet''s surface."},{"id":"q3","question":"Which country is the largest by land area?","options":[{"id":"a","text":"Canada","is_correct":false},{"id":"b","text":"China","is_correct":false},{"id":"c","text":"Russia","is_correct":true},{"id":"d","text":"United States","is_correct":false}],"explanation":"Russia spans eleven time zones and two continents."},{"id":"q4","question":"On which continent is Egypt located?","options":[{"id":"a","text":"Asia","is_correct":false},{"id":"b","text":"Africa","is_correct":true},{"id":"c","text":"Europe","is_correct":false},{"id":"d","text":"Oceania","is_correct":false}],"explanation":"Egypt''s Sinai Peninsula reaches into Asia, but the country is African."},{"id":"q5","question":"What is the capital of Canada?","options":[{"id":"a","text":"Toronto","is_correct":false},{"id":"b","text":"Vancouver","is_correct":false},{"id":"c","text":"Montreal","is_correct":false},{"id":"d","text":"Ottawa","is_correct":true}],"explanation":"Ottawa is in Ontario, on the border with Quebec."},{"id":"q6","question":"Which is the largest hot desert in the world?","options":[{"id":"a","text":"Gobi Desert","is_correct":false},{"id":"b","text":"Sahara Desert","is_correct":true},{"id":"c","text":"Atacama Desert","is_correct":false},{"id":"d","text":"Sonoran Desert","is_correct":false}],"explanation":"The Sahara is roughly the size of the United States."},{"id":"q7","question":"What is the highest mountain above sea level?","options":[{"id":"a","text":"K2","is_correct":false},{"id":"b","text":"Mount Kilimanjaro","is_correct":false},{"id":"c","text":"Mount Everest","is_correct":true},{"id":"d","text":"Denali","is_correct":false}],"explanation":"Everest rises 8,849 metres above sea level, on the Nepal-China border."},{"id":"q8","question":"Which country is shaped like a boot?","options":[{"id":"a","text":"Spain","is_correct":false},{"id":"b","text":"Greece","is_correct":false},{"id":"c","text":"Italy","is_correct":true},{"id":"d","text":"Portugal","is_correct":false}],"explanation":"Italy''s peninsula and the heel of Puglia give the country its boot silhouette."}]'::jsonb,
  null,
  array['geography', 'trivia', 'capitals', 'world']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
