insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-world-street-food-trivia',
  'World Street Food Trivia: 8 Iconic Bites',
  'From tacos al pastor to Osaka''s takoyaki, eight questions on the world''s most famous street food.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"The vertical rotisserie used for tacos al pastor arrived in Mexico with immigrants from which country?","options":[{"id":"a","text":"Spain","is_correct":false},{"id":"b","text":"Lebanon","is_correct":true},{"id":"c","text":"Italy","is_correct":false},{"id":"d","text":"Greece","is_correct":false}],"explanation":"Lebanese immigrants brought the shawarma spit to Mexico in the 20th century, where it became the trompo of tacos al pastor."},{"id":"q2","question":"Banh mi, a sandwich that combines a French baguette with local fillings, is a street food staple of which country?","options":[{"id":"a","text":"Thailand","is_correct":false},{"id":"b","text":"Vietnam","is_correct":true},{"id":"c","text":"South Korea","is_correct":false},{"id":"d","text":"India","is_correct":false}],"explanation":"The banh mi was born in Vietnam during the French colonial era, mixing baguette with Vietnamese fillings."},{"id":"q3","question":"Currywurst, sausage with curried ketchup, was invented in 1949 in which city?","options":[{"id":"a","text":"Munich","is_correct":false},{"id":"b","text":"Vienna","is_correct":false},{"id":"c","text":"Berlin","is_correct":true},{"id":"d","text":"Hamburg","is_correct":false}],"explanation":"Herta Heuwer is credited with mixing ketchup and curry powder in Berlin in 1949."},{"id":"q4","question":"Takoyaki, the fried octopus balls, originated in which Japanese city?","options":[{"id":"a","text":"Osaka","is_correct":true},{"id":"b","text":"Tokyo","is_correct":false},{"id":"c","text":"Kyoto","is_correct":false},{"id":"d","text":"Sapporo","is_correct":false}],"explanation":"Takoyaki was created in Osaka in 1935 and remains a symbol of the city''s street food scene."},{"id":"q5","question":"Arepas, the griddled cakes sold on the streets of Venezuela and Colombia, are made from what?","options":[{"id":"a","text":"Wheat flour","is_correct":false},{"id":"b","text":"Pre-cooked corn flour","is_correct":true},{"id":"c","text":"Rice flour","is_correct":false},{"id":"d","text":"Potato starch","is_correct":false}],"explanation":"Arepas are made from dough of pre-cooked maize flour, a staple since before colonisation."},{"id":"q6","question":"Falafel, the fried snack sold across the Middle East, is usually made from which legume?","options":[{"id":"a","text":"Lentils","is_correct":false},{"id":"b","text":"Chickpeas","is_correct":true},{"id":"c","text":"Kidney beans","is_correct":false},{"id":"d","text":"Soybeans","is_correct":false}],"explanation":"Most falafel is made from ground chickpeas; the Egyptian version, ta''ameya, uses fava beans."},{"id":"q7","question":"Pad Thai, the stir-fried rice noodle dish, is the iconic street food of which country?","options":[{"id":"a","text":"Vietnam","is_correct":false},{"id":"b","text":"Malaysia","is_correct":false},{"id":"c","text":"Thailand","is_correct":true},{"id":"d","text":"Philippines","is_correct":false}],"explanation":"Pad Thai was promoted as Thailand''s national dish in the mid-20th century."},{"id":"q8","question":"Churros dipped in thick hot chocolate are a classic street snack of which country?","options":[{"id":"a","text":"Portugal","is_correct":false},{"id":"b","text":"Spain","is_correct":true},{"id":"c","text":"Argentina","is_correct":false},{"id":"d","text":"France","is_correct":false}],"explanation":"Churros con chocolate are a Spanish tradition, sold at churrerias and street stalls."}]'::jsonb,
  null,
  array['food', 'street-food', 'trivia', 'world-cuisine']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
