insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-tech-and-ai-history-trivia',
  'Tech and AI History Trivia: From ENIAC to Deep Blue',
  'From the first microprocessor to the machine that beat Kasparov, eight milestones of computing and AI.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"In which year did Apple release the first iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2010","is_correct":false}],"explanation":"Steve Jobs introduced the iPhone in January 2007 and it went on sale that June."},{"id":"q2","question":"What does HTTP, the protocol the web runs on, stand for?","options":[{"id":"a","text":"HyperText Transfer Protocol","is_correct":true},{"id":"b","text":"High Throughput Transfer Process","is_correct":false},{"id":"c","text":"HyperText Terminal Program","is_correct":false},{"id":"d","text":"Host Text Transmission Protocol","is_correct":false}],"explanation":"Tim Berners-Lee designed HTTP at CERN in 1989 to serve hypertext documents."},{"id":"q3","question":"Which company built the first commercial microprocessor, the 4004, in 1971?","options":[{"id":"a","text":"IBM","is_correct":false},{"id":"b","text":"Intel","is_correct":true},{"id":"c","text":"Motorola","is_correct":false},{"id":"d","text":"Texas Instruments","is_correct":false}],"explanation":"The Intel 4004, led by Federico Faggin''s team, packed a whole CPU into a single chip."},{"id":"q4","question":"Tim Berners-Lee proposed the World Wide Web in 1989 while working at which organisation?","options":[{"id":"a","text":"MIT","is_correct":false},{"id":"b","text":"CERN","is_correct":true},{"id":"c","text":"NASA","is_correct":false},{"id":"d","text":"IBM","is_correct":false}],"explanation":"He wrote the proposal to share documents between researchers at CERN, the physics lab in Geneva."},{"id":"q5","question":"Which IBM computer defeated reigning world chess champion Garry Kasparov in 1997?","options":[{"id":"a","text":"Watson","is_correct":false},{"id":"b","text":"Deep Blue","is_correct":true},{"id":"c","text":"Deep Thought","is_correct":false},{"id":"d","text":"AlphaZero","is_correct":false}],"explanation":"Deep Blue won the 1997 rematch 3.5 to 2.5, the first match win of a machine over a reigning champion."},{"id":"q6","question":"The term ''artificial intelligence'' was coined at a 1956 workshop at which university?","options":[{"id":"a","text":"Stanford","is_correct":false},{"id":"b","text":"MIT","is_correct":false},{"id":"c","text":"Dartmouth","is_correct":true},{"id":"d","text":"Harvard","is_correct":false}],"explanation":"John McCarthy used the term in the proposal for the Dartmouth Summer Research Project."},{"id":"q7","question":"ENIAC, one of the first general-purpose electronic computers, was completed in which decade?","options":[{"id":"a","text":"The 1930s","is_correct":false},{"id":"b","text":"The 1940s","is_correct":true},{"id":"c","text":"The 1950s","is_correct":false},{"id":"d","text":"The 1960s","is_correct":false}],"explanation":"ENIAC was finished in 1945 at the University of Pennsylvania and announced publicly in 1946."},{"id":"q8","question":"The first message sent over ARPANET in 1969 crashed after which two letters?","options":[{"id":"a","text":"HI","is_correct":false},{"id":"b","text":"LO","is_correct":true},{"id":"c","text":"OK","is_correct":false},{"id":"d","text":"GO","is_correct":false}],"explanation":"UCLA tried to send LOGIN to Stanford, but the system crashed after the first two letters."}]'::jsonb,
  null,
  array['technology', 'ai', 'computers', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-tecnologia-ia',
  'Trivia de tecnologia e IA: del primer chip a la web',
  'Del primer microprocesador a la maquina que vencio a Kasparov: ocho hitos de la informatica y la IA.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"En que ano lanzo Apple el primer iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2010","is_correct":false},{"id":"d","text":"2003","is_correct":false}],"explanation":"Steve Jobs lo presento en enero de 2007 y salio a la venta en junio de ese ano."},{"id":"q2","question":"ARPANET, la red que precedio a internet, envio su primer mensaje en que ano?","options":[{"id":"a","text":"1969","is_correct":true},{"id":"b","text":"1979","is_correct":false},{"id":"c","text":"1983","is_correct":false},{"id":"d","text":"1961","is_correct":false}],"explanation":"En octubre de 1969 UCLA intento enviar LOGIN a Stanford y el sistema cayo tras las letras LO."},{"id":"q3","question":"Que maquina de IBM derroto al campeon mundial de ajedrez Garry Kasparov en 1997?","options":[{"id":"a","text":"Watson","is_correct":false},{"id":"b","text":"Deep Blue","is_correct":true},{"id":"c","text":"AlphaGo","is_correct":false},{"id":"d","text":"ENIAC","is_correct":false}],"explanation":"Deep Blue gano la revancha 3,5 a 2,5, la primera vez que una maquina vencio a un campeon vigente."},{"id":"q4","question":"La World Wide Web fue propuesta en 1989 por Tim Berners-Lee, que trabajaba en que institucion?","options":[{"id":"a","text":"La NASA","is_correct":false},{"id":"b","text":"El CERN","is_correct":true},{"id":"c","text":"El MIT","is_correct":false},{"id":"d","text":"Microsoft","is_correct":false}],"explanation":"La diseno en el CERN, el laboratorio europeo de fisica de particulas en Ginebra."},{"id":"q5","question":"El primer microprocesador comercial, lanzado en 1971, fue el Intel...","options":[{"id":"a","text":"8086","is_correct":false},{"id":"b","text":"4004","is_correct":true},{"id":"c","text":"8008","is_correct":false},{"id":"d","text":"Pentium","is_correct":false}],"explanation":"El Intel 4004 metio una CPU completa en un solo chip por primera vez."},{"id":"q6","question":"El termino ''inteligencia artificial'' se acuno en un seminario de 1956 en que universidad estadounidense?","options":[{"id":"a","text":"Harvard","is_correct":false},{"id":"b","text":"Stanford","is_correct":false},{"id":"c","text":"Dartmouth","is_correct":true},{"id":"d","text":"Berkeley","is_correct":false}],"explanation":"John McCarthy lo propuso para el taller de verano de Dartmouth College."},{"id":"q7","question":"ENIAC, una de las primeras computadoras electronicas de proposito general, se termino en que decada?","options":[{"id":"a","text":"Los anos 30","is_correct":false},{"id":"b","text":"Los anos 40","is_correct":true},{"id":"c","text":"Los anos 50","is_correct":false},{"id":"d","text":"Los anos 60","is_correct":false}],"explanation":"Se completo en 1945 en la Universidad de Pensilvania y se anuncio al publico en 1946."},{"id":"q8","question":"Que supercomputadora de IBM gano el concurso televisivo Jeopardy! en 2011?","options":[{"id":"a","text":"Deep Blue","is_correct":false},{"id":"b","text":"Watson","is_correct":true},{"id":"c","text":"Summit","is_correct":false},{"id":"d","text":"AlphaGo","is_correct":false}],"explanation":"Watson vencio a Ken Jennings y Brad Rutter, dos de los mejores concursantes de la historia del programa."}]'::jsonb,
  null,
  array['tecnologia', 'ia', 'computacion', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
