insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-classic-books-trivia',
  'Classic Books Trivia: 8 Literary Landmarks',
  'From Don Quixote''s horse to the first line of Moby-Dick, eight questions on classics of world literature.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"Who wrote One Hundred Years of Solitude?","options":[{"id":"a","text":"Jorge Luis Borges","is_correct":false},{"id":"b","text":"Gabriel Garcia Marquez","is_correct":true},{"id":"c","text":"Pablo Neruda","is_correct":false},{"id":"d","text":"Julio Cortazar","is_correct":false}],"explanation":"Published in 1967, it made Garcia Marquez the emblem of the Latin American Boom; he won the Nobel Prize in 1982."},{"id":"q2","question":"In Don Quixote, what is the name of the knight''s bony horse?","options":[{"id":"a","text":"Babieca","is_correct":false},{"id":"b","text":"Rocinante","is_correct":true},{"id":"c","text":"Bucephalus","is_correct":false},{"id":"d","text":"Shadowfax","is_correct":false}],"explanation":"Rocinante''s name plays on rocin, a workhorse, and ante, meaning before."},{"id":"q3","question":"Pride and Prejudice was written by which author?","options":[{"id":"a","text":"Charlotte Bronte","is_correct":false},{"id":"b","text":"Jane Austen","is_correct":true},{"id":"c","text":"Emily Dickinson","is_correct":false},{"id":"d","text":"Mary Shelley","is_correct":false}],"explanation":"Austen published it in 1813, her second novel after Sense and Sensibility."},{"id":"q4","question":"Which novel famously opens with the line ''Call me Ishmael''?","options":[{"id":"a","text":"Moby-Dick","is_correct":true},{"id":"b","text":"The Old Man and the Sea","is_correct":false},{"id":"c","text":"Treasure Island","is_correct":false},{"id":"d","text":"Heart of Darkness","is_correct":false}],"explanation":"Herman Melville''s whaling epic was published in 1851."},{"id":"q5","question":"In George Orwell''s 1984, which figure watches over the citizens of Oceania?","options":[{"id":"a","text":"Emmanuel Goldstein","is_correct":false},{"id":"b","text":"Big Brother","is_correct":true},{"id":"c","text":"O''Brien","is_correct":false},{"id":"d","text":"The Inner Party","is_correct":false}],"explanation":"Big Brother is watching you; Goldstein is the supposed enemy of the state."},{"id":"q6","question":"Shakespeare''s Romeo and Juliet is set in which Italian city?","options":[{"id":"a","text":"Venice","is_correct":false},{"id":"b","text":"Verona","is_correct":true},{"id":"c","text":"Florence","is_correct":false},{"id":"d","text":"Rome","is_correct":false}],"explanation":"The feuding Montague and Capulet families live in Verona."},{"id":"q7","question":"Who wrote Crime and Punishment, the novel of the student Raskolnikov?","options":[{"id":"a","text":"Leo Tolstoy","is_correct":false},{"id":"b","text":"Fyodor Dostoevsky","is_correct":true},{"id":"c","text":"Anton Chekhov","is_correct":false},{"id":"d","text":"Ivan Turgenev","is_correct":false}],"explanation":"Dostoevsky published it in 1866; it follows Raskolnikov after he murders a pawnbroker."},{"id":"q8","question":"The Little Prince was written by which French aviator?","options":[{"id":"a","text":"Antoine de Saint-Exupery","is_correct":true},{"id":"b","text":"Victor Hugo","is_correct":false},{"id":"c","text":"Albert Camus","is_correct":false},{"id":"d","text":"Jules Verne","is_correct":false}],"explanation":"Published in 1943, it is among the best-selling and most translated books in history."}]'::jsonb,
  null,
  array['literature', 'books', 'classics', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-libros-clasicos',
  'Trivia de libros clasicos: de Cervantes a Garcia Marquez',
  'Del escudero del Quijote al asteroide del Principito: ocho preguntas sobre clasicos de la literatura universal.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"En que ano se publico Cien anos de soledad, de Gabriel Garcia Marquez?","options":[{"id":"a","text":"1957","is_correct":false},{"id":"b","text":"1967","is_correct":true},{"id":"c","text":"1975","is_correct":false},{"id":"d","text":"1982","is_correct":false}],"explanation":"Se publico en 1967 y dio impulso al Boom latinoamericano; su autor gano el Nobel en 1982."},{"id":"q2","question":"Como se llama el escudero que acompana a Don Quijote en sus salidas?","options":[{"id":"a","text":"Sancho Panza","is_correct":true},{"id":"b","text":"Sanson Carrasco","is_correct":false},{"id":"c","text":"Rocinante","is_correct":false},{"id":"d","text":"El Bachiller","is_correct":false}],"explanation":"Sancho Panza lo sigue a lomos de su burro; Rocinante es el caballo del hidalgo."},{"id":"q3","question":"Matar a un ruisenor, la novela sobre un juicio en el sur de Estados Unidos, la escribio que autora?","options":[{"id":"a","text":"Harper Lee","is_correct":true},{"id":"b","text":"Toni Morrison","is_correct":false},{"id":"c","text":"Louisa May Alcott","is_correct":false},{"id":"d","text":"Virginia Woolf","is_correct":false}],"explanation":"Harper Lee la publico en 1960 y gano el Premio Pulitzer en 1961."},{"id":"q4","question":"Que novela de Mary Shelley narra la creacion de un ser por el doctor Victor Frankenstein?","options":[{"id":"a","text":"Dracula","is_correct":false},{"id":"b","text":"Frankenstein","is_correct":true},{"id":"c","text":"El retrato de Dorian Gray","is_correct":false},{"id":"d","text":"Jane Eyre","is_correct":false}],"explanation":"Shelley la publico en 1818 tras concebirla durante el famoso verano de 1816 en Ginebra."},{"id":"q5","question":"En El principito, el protagonista proviene de cual de estos lugares?","options":[{"id":"a","text":"Marte","is_correct":false},{"id":"b","text":"El asteroide B-612","is_correct":true},{"id":"c","text":"Venus","is_correct":false},{"id":"d","text":"El planeta del rey","is_correct":false}],"explanation":"El principito vive en el asteroide B-612 con su rosa y tres volcanes."},{"id":"q6","question":"Que autor ruso escribio Guerra y paz y Anna Karenina?","options":[{"id":"a","text":"Fiodor Dostoievski","is_correct":false},{"id":"b","text":"Leon Tolstoi","is_correct":true},{"id":"c","text":"Nikolai Gogol","is_correct":false},{"id":"d","text":"Anton Chejov","is_correct":false}],"explanation":"Tolstoi publico Guerra y paz entre 1865 y 1869 y Anna Karenina entre 1875 y 1877."},{"id":"q7","question":"La Odisea, el poema epico sobre el regreso de Odiseo a Itaca, se atribuye a que poeta griego?","options":[{"id":"a","text":"Homero","is_correct":true},{"id":"b","text":"Hesiodo","is_correct":false},{"id":"c","text":"Sofocles","is_correct":false},{"id":"d","text":"Esquilo","is_correct":false}],"explanation":"Homero es tambien el autor atribuido de la Iliada; ambos poemas se fijaron por escrito hacia el siglo VIII a. C."},{"id":"q8","question":"Que dramaturgo ingles escribio Hamlet, Macbeth y Otelo?","options":[{"id":"a","text":"Oscar Wilde","is_correct":false},{"id":"b","text":"William Shakespeare","is_correct":true},{"id":"c","text":"Christopher Marlowe","is_correct":false},{"id":"d","text":"George Bernard Shaw","is_correct":false}],"explanation":"Shakespeare escribio unas 39 obras entre finales del siglo XVI y comienzos del XVII."}]'::jsonb,
  null,
  array['literatura', 'libros', 'clasicos', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-space-missions-trivia',
  'Space Missions Trivia: From Sputnik to Mars',
  'Sputnik, Apollo 11 and Voyager''s Golden Record: eight questions on the missions that took us to space.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Which mission landed the first humans on the Moon?","options":[{"id":"a","text":"Apollo 8","is_correct":false},{"id":"b","text":"Apollo 11","is_correct":true},{"id":"c","text":"Apollo 13","is_correct":false},{"id":"d","text":"Gemini 4","is_correct":false}],"explanation":"Armstrong and Aldrin walked on the Moon on 20 July 1969; Apollo 8 had only orbited it."},{"id":"q2","question":"What was the name of the first artificial satellite, launched in 1957?","options":[{"id":"a","text":"Explorer 1","is_correct":false},{"id":"b","text":"Sputnik 1","is_correct":true},{"id":"c","text":"Vostok 1","is_correct":false},{"id":"d","text":"Telstar","is_correct":false}],"explanation":"The Soviet Sputnik 1 was a polished sphere with four antennas that beeped for three weeks."},{"id":"q3","question":"Who was the first human to travel into space?","options":[{"id":"a","text":"Alan Shepard","is_correct":false},{"id":"b","text":"Yuri Gagarin","is_correct":true},{"id":"c","text":"John Glenn","is_correct":false},{"id":"d","text":"Neil Armstrong","is_correct":false}],"explanation":"Gagarin completed one orbit of Earth aboard Vostok 1 on 12 April 1961."},{"id":"q4","question":"Which Soviet-Russian space station operated in low Earth orbit from 1986 to 2001?","options":[{"id":"a","text":"Skylab","is_correct":false},{"id":"b","text":"Mir","is_correct":true},{"id":"c","text":"Salyut 1","is_correct":false},{"id":"d","text":"Tiangong","is_correct":false}],"explanation":"Mir hosted crews for 15 years before being deorbited over the Pacific Ocean."},{"id":"q5","question":"Voyager 1, launched in 1977, carries which artifact as a message to any finder?","options":[{"id":"a","text":"A golden record","is_correct":true},{"id":"b","text":"A microfilm library","is_correct":false},{"id":"c","text":"A radio beacon","is_correct":false},{"id":"d","text":"A silicon chip archive","is_correct":false}],"explanation":"The Golden Record holds sounds, greetings in 55 languages and images of Earth."},{"id":"q6","question":"Which NASA rover landed on Mars in August 2012?","options":[{"id":"a","text":"Sojourner","is_correct":false},{"id":"b","text":"Curiosity","is_correct":true},{"id":"c","text":"Perseverance","is_correct":false},{"id":"d","text":"Opportunity","is_correct":false}],"explanation":"Curiosity landed in Gale crater in 2012; Perseverance followed in 2021."},{"id":"q7","question":"The Hubble Space Telescope was launched in which year?","options":[{"id":"a","text":"1985","is_correct":false},{"id":"b","text":"1990","is_correct":true},{"id":"c","text":"1998","is_correct":false},{"id":"d","text":"2003","is_correct":false}],"explanation":"Hubble launched aboard shuttle Discovery in April 1990; its mirror flaw was fixed in 1993."},{"id":"q8","question":"Who was the first woman in space?","options":[{"id":"a","text":"Valentina Tereshkova","is_correct":true},{"id":"b","text":"Sally Ride","is_correct":false},{"id":"c","text":"Svetlana Savitskaya","is_correct":false},{"id":"d","text":"Mae Jemison","is_correct":false}],"explanation":"Tereshkova flew solo on Vostok 6 in 1963; Sally Ride was the first American woman, in 1983."}]'::jsonb,
  null,
  array['space', 'science', 'nasa', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-misiones-espaciales',
  'Trivia de misiones espaciales: del Sputnik a Marte',
  'De la primera orbita tripulada a los rovers de Marte: ocho preguntas sobre las misiones que nos llevaron al espacio.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Que astronauta fue el primero en pisar la Luna?","options":[{"id":"a","text":"Buzz Aldrin","is_correct":false},{"id":"b","text":"Neil Armstrong","is_correct":true},{"id":"c","text":"Michael Collins","is_correct":false},{"id":"d","text":"Yuri Gagarin","is_correct":false}],"explanation":"Armstrong piso la superficie el 20 de julio de 1969 durante la mision Apolo 11."},{"id":"q2","question":"Como se llamaba la perra sovietica que orbito la Tierra en 1957, a bordo del Sputnik 2?","options":[{"id":"a","text":"Belka","is_correct":false},{"id":"b","text":"Laika","is_correct":true},{"id":"c","text":"Strelka","is_correct":false},{"id":"d","text":"Zvezdochka","is_correct":false}],"explanation":"Laika fue el primer ser vivo en orbitar la Tierra, solo un mes despues del Sputnik 1."},{"id":"q3","question":"En que ano viajo Yuri Gagarin al espacio, convirtiendose en la primera persona en hacerlo?","options":[{"id":"a","text":"1957","is_correct":false},{"id":"b","text":"1961","is_correct":true},{"id":"c","text":"1963","is_correct":false},{"id":"d","text":"1969","is_correct":false}],"explanation":"Gagarin completo una orbita terrestre en el Vostok 1 el 12 de abril de 1961."},{"id":"q4","question":"El primer modulo de la Estacion Espacial Internacional se lanzo en que ano?","options":[{"id":"a","text":"1986","is_correct":false},{"id":"b","text":"1998","is_correct":true},{"id":"c","text":"2001","is_correct":false},{"id":"d","text":"1990","is_correct":false}],"explanation":"El modulo ruso Zarya despego en noviembre de 1998; la EEI lleva tripulada sin interrupcion desde 2000."},{"id":"q5","question":"La sonda Voyager 1, lanzada en 1977, porta que mensaje para quien la encuentre?","options":[{"id":"a","text":"Una biblioteca en microfilme","is_correct":false},{"id":"b","text":"Un disco dorado","is_correct":true},{"id":"c","text":"Una capsula de ADN","is_correct":false},{"id":"d","text":"Un mapa estelar impreso","is_correct":false}],"explanation":"El Disco de Oro contiene sonidos, saludos en 55 idiomas e imagenes de la Tierra."},{"id":"q6","question":"Que rover de la NASA aterrizo en Marte en febrero de 2021 con el helicoptero Ingenuity?","options":[{"id":"a","text":"Curiosity","is_correct":false},{"id":"b","text":"Perseverance","is_correct":true},{"id":"c","text":"Spirit","is_correct":false},{"id":"d","text":"Opportunity","is_correct":false}],"explanation":"Perseverance e Ingenuity llegaron al crater Jezero; el helicoptero realizo 72 vuelos."},{"id":"q7","question":"El telescopio espacial Hubble fue lanzado en que ano?","options":[{"id":"a","text":"1990","is_correct":true},{"id":"b","text":"1980","is_correct":false},{"id":"c","text":"1998","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"Despego en abril de 1990 a bordo del transbordador Discovery; en 1993 se corrigio su espejo defectuoso."},{"id":"q8","question":"En que nave viajo Valentina Tereshkova, la primera mujer en el espacio?","options":[{"id":"a","text":"Vostok 1","is_correct":false},{"id":"b","text":"Vostok 6","is_correct":true},{"id":"c","text":"Soyuz 1","is_correct":false},{"id":"d","text":"Mercury-Atlas 6","is_correct":false}],"explanation":"Tereshkova volo sola en el Vostok 6 en junio de 1963, con solo 26 anos."}]'::jsonb,
  null,
  array['espacio', 'ciencia', 'nasa', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-endangered-species-trivia',
  'Endangered Species Trivia: Animals on the Brink',
  'From the vaquita of the Gulf of California to the kakapo of New Zealand, eight questions on Earth''s rarest animals.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"The giant panda''s only wild habitat is in the mountain ranges of which country?","options":[{"id":"a","text":"Japan","is_correct":false},{"id":"b","text":"China","is_correct":true},{"id":"c","text":"India","is_correct":false},{"id":"d","text":"Nepal","is_correct":false}],"explanation":"Wild pandas live mainly in the bamboo forests of Sichuan province, China."},{"id":"q2","question":"The vaquita, the world''s rarest marine mammal, lives only in which body of water?","options":[{"id":"a","text":"The Caribbean Sea","is_correct":false},{"id":"b","text":"The Gulf of California","is_correct":true},{"id":"c","text":"The Coral Sea","is_correct":false},{"id":"d","text":"The Bay of Bengal","is_correct":false}],"explanation":"Fewer than a dozen vaquitas are believed to remain in the northern Gulf of California."},{"id":"q3","question":"The kakapo, a flightless nocturnal parrot, is native to which country?","options":[{"id":"a","text":"Australia","is_correct":false},{"id":"b","text":"New Zealand","is_correct":true},{"id":"c","text":"Madagascar","is_correct":false},{"id":"d","text":"Brazil","is_correct":false}],"explanation":"Fewer than 250 kakapos survive, all on predator-free islands of New Zealand."},{"id":"q4","question":"The Amur leopard, among the rarest big cats, lives mainly in which region?","options":[{"id":"a","text":"The Amazon basin","is_correct":false},{"id":"b","text":"The Russian Far East","is_correct":true},{"id":"c","text":"The Serengeti","is_correct":false},{"id":"d","text":"The Himalayas of Nepal","is_correct":false}],"explanation":"Most remaining Amur leopards live in the forests along the Russia-China border."},{"id":"q5","question":"Which is the largest living species of rhinoceros?","options":[{"id":"a","text":"Indian rhinoceros","is_correct":false},{"id":"b","text":"White rhinoceros","is_correct":true},{"id":"c","text":"Black rhinoceros","is_correct":false},{"id":"d","text":"Javan rhinoceros","is_correct":false}],"explanation":"The white rhino can exceed 2,000 kg; the southern subspecies recovered from fewer than 100 animals."},{"id":"q6","question":"All remaining wild Javan rhinos live inside which national park?","options":[{"id":"a","text":"Komodo National Park","is_correct":false},{"id":"b","text":"Ujung Kulon","is_correct":true},{"id":"c","text":"Chitwan","is_correct":false},{"id":"d","text":"Kruger","is_correct":false}],"explanation":"Ujung Kulon, at the western tip of Java, holds the only known population of about 70 animals."},{"id":"q7","question":"The mountain gorilla survives mainly in the forests of which region?","options":[{"id":"a","text":"The cloud forests of Central America","is_correct":false},{"id":"b","text":"The Virunga mountains of Central Africa","is_correct":true},{"id":"c","text":"The lowlands of Borneo","is_correct":false},{"id":"d","text":"The Congo savanna","is_correct":false}],"explanation":"Mountain gorillas live in the Virunga volcanoes region shared by Rwanda, Uganda and DR Congo."},{"id":"q8","question":"What does the IUCN Red List measure?","options":[{"id":"a","text":"Species'' risk of extinction","is_correct":true},{"id":"b","text":"Animal population growth","is_correct":false},{"id":"c","text":"Habitat quality","is_correct":false},{"id":"d","text":"Illegal trade volume","is_correct":false}],"explanation":"The Red List ranks species from Least Concern to Extinct according to their extinction risk."}]'::jsonb,
  null,
  array['animals', 'conservation', 'nature', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-especies-amenazadas',
  'Trivia de especies amenazadas: animales al borde',
  'De la vaquita del golfo de California al kakapo de Nueva Zelanda: ocho preguntas sobre los animales mas raros del planeta.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"La mayoria de los pandas gigantes salvajes vive en los bosques de bambu de que provincia china?","options":[{"id":"a","text":"Yunnan","is_correct":false},{"id":"b","text":"Sichuan","is_correct":true},{"id":"c","text":"Guangdong","is_correct":false},{"id":"d","text":"Heilongjiang","is_correct":false}],"explanation":"Las montanas de Sichuan concentran la mayor parte del habitat silvestre del panda."},{"id":"q2","question":"La vaquita, el mamifero marino mas raro del mundo, vive unicamente en que lugar?","options":[{"id":"a","text":"El mar Caribe","is_correct":false},{"id":"b","text":"El golfo de California","is_correct":true},{"id":"c","text":"El mar de Bering","is_correct":false},{"id":"d","text":"La bahia de Bengala","is_correct":false}],"explanation":"Se estima que quedan menos de una decena de vaquitas en el norte del golfo de California."},{"id":"q3","question":"El kakapo, un loro nocturno incapaz de volar, es originario de que pais?","options":[{"id":"a","text":"Australia","is_correct":false},{"id":"b","text":"Nueva Zelanda","is_correct":true},{"id":"c","text":"Madagascar","is_correct":false},{"id":"d","text":"Papua Nueva Guinea","is_correct":false}],"explanation":"Sobreviven menos de 250 kakapos, todos en islas libres de depredadores de Nueva Zelanda."},{"id":"q4","question":"El leopardo de Amur habita los bosques de la frontera entre Rusia y que otro pais?","options":[{"id":"a","text":"Mongolia","is_correct":false},{"id":"b","text":"China","is_correct":true},{"id":"c","text":"Kazajistan","is_correct":false},{"id":"d","text":"Corea del Sur","is_correct":false}],"explanation":"La mayor parte de los leopardos de Amur que quedan vive en el Lejano Oriente ruso y el noreste de China."},{"id":"q5","question":"Cual es la especie de rinoceronte mas grande que existe hoy?","options":[{"id":"a","text":"Rinoceronte negro","is_correct":false},{"id":"b","text":"Rinoceronte blanco","is_correct":true},{"id":"c","text":"Rinoceronte indio","is_correct":false},{"id":"d","text":"Rinoceronte de Java","is_correct":false}],"explanation":"El rinoceronte blanco puede superar los 2.000 kg; la subespecie del sur se recupero de menos de 100 ejemplares."},{"id":"q6","question":"Todos los rinocerontes de Java salvajes que quedan viven dentro de que parque nacional?","options":[{"id":"a","text":"Komodo","is_correct":false},{"id":"b","text":"Ujung Kulon","is_correct":true},{"id":"c","text":"Chitwan","is_correct":false},{"id":"d","text":"Kruger","is_correct":false}],"explanation":"Ujung Kulon, en el extremo oeste de Java, alberga la unica poblacion conocida, de unos 70 animales."},{"id":"q7","question":"El gorila de montana sobrevive sobre todo en los bosques de que region?","options":[{"id":"a","text":"Los volcanes Virunga, en Africa central","is_correct":true},{"id":"b","text":"Las selvas de Borneo","is_correct":false},{"id":"c","text":"Los Andes colombianos","is_correct":false},{"id":"d","text":"Las montanas de Madagascar","is_correct":false}],"explanation":"Habita la region de los volcanes Virunga, compartida por Ruanda, Uganda y la RD del Congo."},{"id":"q8","question":"Que mide la Lista Roja de la UICN?","options":[{"id":"a","text":"El crecimiento de las poblaciones","is_correct":false},{"id":"b","text":"El riesgo de extincion de las especies","is_correct":true},{"id":"c","text":"La calidad del habitat","is_correct":false},{"id":"d","text":"El volumen del trafico ilegal","is_correct":false}],"explanation":"La Lista Roja clasifica a las especies de Preocupacion Menor a Extinta segun su riesgo de extincion."}]'::jsonb,
  null,
  array['animales', 'conservacion', 'naturaleza', 'trivia']::text[],
  4,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

